// Parse HTML and extract Zillow property data
const item = $input.first();

// Get HTML from Scrape.do response
const html = item.json.data || item.json.body || item.json;

// Skip if no HTML content
if (!html || typeof html !== 'string') {
  return [];
}

// Get the original URL
const originalUrl = $('Read Zillow URLs from Google Sheets').first().json.URLs || 'N/A';

// Extract Price - improved regex
let price = 'N/A';
// Try multiple patterns
const pricePattern1 = html.match(/data-testid="price"[^>]*>\s*\$?([0-9,]+)\s*</)
const pricePattern2 = html.match(/"price"[^}]*"value"\s*:\s*"?\$?([0-9,]+)"?/)
const pricePattern3 = html.match(/\$([0-9]{3},[0-9]{3}(?:,[0-9]{3})?)(?!\d)/)

if (pricePattern1) {
  price = '$' + pricePattern1[1].trim();
} else if (pricePattern2) {
  price = '$' + pricePattern2[1].trim();
} else if (pricePattern3) {
  price = pricePattern3[0].trim();
}

// Extract Address, City, and State
let street = 'N/A';
let city = 'N/A';
let state = 'N/A';

const addressMatch = html.match(/(\d+\s+[^,]+),\s*([^,]+),\s*(\w{2})\s+\d{5}/);
if (addressMatch) {
  street = addressMatch[1].trim();
  city = addressMatch[2].trim();
  state = addressMatch[3].trim();
}

// Extract Days on Zillow
let daysOnZillow = 'N/A';
const daysMatch = html.match(/(\d+)\s+days?\s*on\s+Zillow/i);
if (daysMatch) {
  daysOnZillow = daysMatch[1];
}

// Extract Zestimate
let zestimate = 'N/A';
const zestimateMatch = html.match(/\$[\d,]+(?=\s*Zestimate)/);
if (zestimateMatch) {
  zestimate = zestimateMatch[0];
}

// Return ONLY structured data
return [{
  json: {
    URL: originalUrl,
    Price: price,
    Address: street,
    City: city,
    State: state,
    'Days on Zillow': daysOnZillow,
    Zestimate: zestimate,
    'Scraped At': new Date().toISOString()
  }
}];
